import React, { useState } from 'react';
import { useApp } from '../context/AppContext';

export default function Colleges() {
  const { user, selectedCollege, setSelectedCollege, setPage, dark } = useApp();
  const [search, setSearch] = useState('');

  const colleges =
    user?.role === 'student' && user?.college
      ? [user.college]
      : selectedCollege
      ? [selectedCollege]
      : [];

  return (
    <div style={{ padding: 24 }}>
      <h1 style={{ fontSize: 26, fontWeight: 800 }}>
        Your College
      </h1>

      {/* Search */}
      <input
        placeholder="Search college..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        style={{
          marginTop: 16,
          padding: 10,
          width: '100%',
          maxWidth: 400,
          borderRadius: 10,
          border: dark ? '1px solid #333' : '1px solid #ddd',
          background: dark ? '#0f172a' : '#ffffff',
          color: dark ? '#fff' : '#000'
        }}
      />

      {/* Grid */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
          gap: 20,
          marginTop: 24
        }}
      >
        {colleges.map((c) => (
          <div
            key={c._id}
            onClick={() => {
              setSelectedCollege(c);
              setPage('resources');
            }}
            style={{
              padding: 20,
              borderRadius: 20,
              background: dark ? '#0b1120' : '#ffffff',
              border: dark
                ? '1px solid rgba(255,255,255,0.08)'
                : '1px solid rgba(0,0,0,0.08)',
              cursor: 'pointer',
              transition: 'all 0.3s ease'
            }}
            onMouseEnter={(e) =>
              (e.currentTarget.style.transform = 'translateY(-5px)')
            }
            onMouseLeave={(e) =>
              (e.currentTarget.style.transform = 'translateY(0)')
            }
          >
            {/* Top */}
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <div
                style={{
                  width: 50,
                  height: 50,
                  borderRadius: 12,
                  background: dark
                    ? 'rgba(99,102,241,0.2)'
                    : 'rgba(99,102,241,0.1)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: 24
                }}
              >
                🏫
              </div>

              <div style={{ color: '#f59e0b', fontWeight: 700 }}>
                ⭐ {c.rating || 4.5}
              </div>
            </div>

            {/* Short */}
            <div
              style={{
                marginTop: 12,
                color: '#6366f1',
                fontSize: 12
              }}
            >
              {c.short}
            </div>

            {/* Name */}
            <h3
              style={{
                marginTop: 6,
                fontSize: 16,
                color: dark ? '#fff' : '#0f0f23'
              }}
            >
              {c.name}
            </h3>

            {/* City */}
            <p
              style={{
                color: dark ? '#94a3b8' : '#64748b',
                fontSize: 13
              }}
            >
              📍 {c.city} · Est. {c.established}
            </p>

            {/* Footer */}
            <div
              style={{
                marginTop: 14,
                paddingTop: 10,
                borderTop: dark
                  ? '1px solid rgba(255,255,255,0.05)'
                  : '1px solid rgba(0,0,0,0.05)',
                display: 'flex',
                justifyContent: 'space-between',
                fontSize: 13,
                color: dark ? '#94a3b8' : '#64748b'
              }}
            >
              <span>View resources</span>
              <span style={{ color: '#6366f1' }}>→</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
